<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$user=require_user();$error='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$action=$_POST['action']??'';if($action==='profile'){$display=trim($_POST['display_name']??'');db()->prepare('UPDATE users SET display_name=?,updated_at=NOW() WHERE id=?')->execute([substr($display,0,80),$user['id']]);$ok='Profil aktualisiert.';$user=require_user();}elseif($action==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$q=db()->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$user['id']]);$hash=(string)$q->fetchColumn();if(!password_verify($old,$hash))$error='Das aktuelle Passwort ist nicht korrekt.';elseif(strlen($new)<10)$error='Das neue Passwort muss mindestens 10 Zeichen lang sein.';else{db()->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$user['id']]);db()->prepare('UPDATE api_tokens SET revoked_at=NOW() WHERE user_id=?')->execute([$user['id']]);$ok='Passwort geändert. App-Tokens wurden aus Sicherheitsgründen abgemeldet.';}}}$q=db()->prepare('SELECT id,device_name,created_at,last_used_at,expires_at FROM api_tokens WHERE user_id=? AND revoked_at IS NULL ORDER BY created_at DESC');$q->execute([$user['id']]);$tokens=$q->fetchAll();$pageTitle='Konto';require __DIR__.'/includes/header.php';?>
<section class="dashboard"><div class="container"><h1>Konto</h1><p class="section-lead">Kontodaten und später verbundene Just-InCard-Geräte verwalten.</p><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><?php if($ok):?><div class="alert alert-ok"><?=e($ok)?></div><?php endif;?><div class="wide-grid"><div class="panel card-panel"><h3>Profil</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="form-row"><label>Benutzername</label><input class="input" value="<?=e($user['username'])?>" disabled></div><div class="form-row"><label>E-Mail</label><input class="input" value="<?=e($user['email'])?>" disabled></div><div class="form-row"><label>Anzeigename</label><input class="input" name="display_name" maxlength="80" value="<?=e($user['display_name'])?>"></div><button class="btn btn-primary">Speichern</button></form></div><div class="panel card-panel"><h3>Passwort ändern</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><div class="form-row"><label>Aktuelles Passwort</label><input class="input" type="password" name="old_password" required></div><div class="form-row"><label>Neues Passwort</label><input class="input" type="password" name="new_password" minlength="10" required></div><button class="btn">Passwort ändern</button></form></div></div><div class="panel card-panel" style="margin-top:18px"><h3>Verbundene App-Sitzungen</h3><?php if(!$tokens):?><p class="subtle">Noch keine Windows-/Android-App mit diesem Konto verbunden.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Gerät</th><th>Erstellt</th><th>Zuletzt verwendet</th><th>Gültig bis</th></tr></thead><tbody><?php foreach($tokens as $t):?><tr><td><?=e($t['device_name']?:'Just InCard Gerät')?></td><td><?=e($t['created_at'])?></td><td><?=e($t['last_used_at']?:'–')?></td><td><?=e($t['expires_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section>
